            this.x1 = Math.min(x1, x2);
            this.y1 = Math.min(y1, y2);
            this.x2 = Math.max(x1, x2);
            this.y2 = Math.max(y1, y2);
        }

        int distanceTo(Rectangle other) {
            int dx = 0;
            if (this.x2 < other.x1) {
                dx = other.x1 - this.x2;
            } else if (other.x2 < this.x1) {
                dx = this.x1 - other.x2;
            }

            int dy = 0;
            if (this.y2 < other.y1) {
                dy = other.y1 - this.y2;
            } else if (other.y2 < this.y1) {
                dy = this.y1 - other.y2;
            }

            return dx + dy;
        }
    }

    static class FastScanner {
